#[derive(Debug)]
enum MyErr { Empty }
fn f(v: &[i32]) -> Result<i32, MyErr> {
    if v.is_empty() { return Err(MyErr::Empty); }
    Ok(v[0])
}
println!("{:?} {:?}", f(&[]), f(&[3]));

